package mypackage5z7;

public class Pattern3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
			for(int i=1;i<7;i++) {

		    	  for(int j=1;j<i;j++) {

		    		  System.out.print(" ");

		    	  }

		    	  for(char k='A';k<'H'-i;k++) {

		    		  System.out.print(k);

		    	  }

		    	  System.out.println();

		      }

			}
		
}
